import{_ as t,C as n,o,c as r,E as i,a2 as s}from"./chunks/framework.Cm6XCzck.js";const c="/joinwell52/assets/covers/daily-2026-08-19-taskbook-five-stage-pipeline-en.png",f=JSON.parse('{"title":"How Do You Turn a 20,000-Word Requirement into a Task Graph an Agent Team Can Execute?","description":"","frontmatter":{"title":"How Do You Turn a 20,000-Word Requirement into a Task Graph an Agent Team Can Execute?","date":"2026-08-19","column":"open-source-engineering","category":"daily","article_type":"project-research","edition":"research-center","research_question":"How can a long requirement be compiled into a traceable, testable, approvable, and recoverable multi-agent work graph?","summary":"A long requirement should become an accountable construction plan with provenance, dependencies, tests, evidence, and recovery—not a polished summary—before deterministic validation and human approval open execution.","item_id":"MANUAL-20260819-TASKGRAPH","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-19-taskbook-to-task-graph-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-fact-claim-matrices.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-experiment-run-log.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/03-independent-final-package-review-round2.md"]},"headers":[],"relativePath":"en/engineering/2026-08-19-taskbook-to-task-graph.md","filePath":"en/engineering/2026-08-19-taskbook-to-task-graph.md","lastUpdated":1787125010000}'),l={name:"en/engineering/2026-08-19-taskbook-to-task-graph.md"};function d(p,e,h,u,m,g){const a=n("ArticleCover");return o(),r("div",null,[i(a,{image:"/assets/covers/daily-2026-08-19-taskbook-to-task-graph-cover.png",kicker:"Open-source Engineering · Project Research",title:"How Do You Turn a 20,000-Word Requirement into a Task Graph an Agent Team Can Execute?",summary:"A long requirement should become an accountable construction plan with provenance, dependencies, tests, evidence, and recovery—not a polished summary—before deterministic validation and human approval open execution.",version:"MANUAL-20260819-TASKGRAPH",status:"Independent Editorial PASS · 2026-08-19",languageHref:"/zh/engineering/2026-08-19-taskbook-to-task-graph",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="how-do-you-turn-a-20-000-word-requirement-into-a-task-graph-an-agent-team-can-execute" tabindex="-1">How Do You Turn a 20,000-Word Requirement into a Task Graph an Agent Team Can Execute? <a class="header-anchor" href="#how-do-you-turn-a-20-000-word-requirement-into-a-task-graph-an-agent-team-can-execute" aria-label="Permalink to &quot;How Do You Turn a 20,000-Word Requirement into a Task Graph an Agent Team Can Execute?&quot;">​</a></h1><p><strong>Series map:</strong> this article turns a long requirement into an executable work graph. Continue with <a href="/joinwell52/en/engineering/2026-08-19-agent-dispatch-fault-injection">fault-injection testing</a>, then <a href="/joinwell52/en/digital-employee/2026-08-19-local-runtime-mobile-control">local execution with mobile control</a>. The three articles cover planning, verification, and remote oversight.</p><h2 id="in-ten-seconds" tabindex="-1">In ten seconds <a class="header-anchor" href="#in-ten-seconds" aria-label="Permalink to &quot;In ten seconds&quot;">​</a></h2><p>Do not ask an AI team to turn a long requirement into a polished summary. Turn it into a construction plan in which every requirement has an owner, an acceptance check, a dependency, evidence, and a recovery path.</p><p>The method has three controls: preserve a read record that reaches the final line, turn requirements into accountable work cards, and require a version-bound human decision before the first card opens. A source change invalidates the old approval.</p><p>Imagine a specification that says: add mobile approvals to a local AI development team; preserve the existing task protocol; do not expand publication authority in the open edition; support Windows; provide rollback; and complete a security review before release.</p><p>If you hand the entire document to an agent, the easiest output is a polished summary. A summary tends to preserve <em>what to build</em> while losing three things that decide whether the work is governable: which sentence is mandatory, which claim depends on the current repository, and which action must stop for a human decision.</p><p>Cursor&#39;s official Plan Mode starts complex work in the right place: research the repository, clarify requirements, create an editable plan, and wait for approval. A 20,000-word taskbook, however, needs more than a longer Markdown checklist. It needs a reviewable compilation pipeline.</p><blockquote><p><strong>Long-horizon planning is not compression. It is the compilation of natural language into traceable, testable, and decidable engineering artifacts.</strong></p></blockquote><p><img src="'+c+`" alt="A five-stage responsibility chain from source locking and requirement ledger to validation, dispatch, and acceptance"></p><p><em>Figure 1. Each stage names its input, accountable role, output, and blocking condition. The ledger and work packages belong to CodeFlowMu planning; formal collaboration then uses FCoP TASK, REPORT, and REVIEW artifacts. Source: CodeFlowMu long-task planning contract, PM planning-governance specification, and FCoP v3.</em></p><h2 id="prove-that-the-read-record-covers-the-input" tabindex="-1">Prove that the read record covers the input <a class="header-anchor" href="#prove-that-the-read-record-covers-the-input" aria-label="Permalink to &quot;Prove that the read record covers the input&quot;">​</a></h2><p>The first output should be a source record: version, byte digest, line count, read time, whether EOF was reached, and the attachments and external references used by the document.</p><p>This mechanical step catches a practical failure. A truncated input may retain “mobile approval” while dropping “publication authority must not change” and “Windows regression is required” from the final pages. Every later plan can be coherent and still be based on an incomplete source. Reaching the final line proves coverage of the read record, not model understanding; the ledger and acceptance checks still have to prove that each requirement was used correctly.</p><p><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-core-specification-s1.0" target="_blank" rel="noreferrer">TMPA Core S1.0</a> treats provenance, identity, references, and reconstructable history as governed behavior. CodeFlowMu&#39;s current <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/skills/pm-long-horizon-planning/references/planning-model-contract.md" target="_blank" rel="noreferrer">long-horizon planning contract</a> goes further by recording the source path, version, SHA-256, line count, complete read ranges, and references. That is a project method, not an industry standard, but it turns “I read it” into an inspectable fact.</p><h2 id="build-a-requirement-ledger-before-scheduling-work-packages" tabindex="-1">Build a Requirement Ledger before scheduling work packages <a class="header-anchor" href="#build-a-requirement-ledger-before-scheduling-work-packages" aria-label="Permalink to &quot;Build a Requirement Ledger before scheduling work packages&quot;">​</a></h2><p>After complete ingestion, extract every actionable statement into a ledger. A minimal row contains:</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th><th>Example</th></tr></thead><tbody><tr><td><code>REQ-ID</code></td><td>Stable identity</td><td><code>REQ-0042</code></td></tr><tr><td>Source location</td><td>Return to the exact wording</td><td>Lines 318–325</td></tr><tr><td>Kind</td><td>Must / goal / current fact / estimate / assumption / authority boundary</td><td>Authority boundary</td></tr><tr><td>Normalized requirement</td><td>One testable sentence</td><td>The open edition must not own PWA publication authority</td></tr><tr><td>Acceptor</td><td>Who may decide</td><td>ADMIN</td></tr><tr><td>Downstream mapping</td><td>WP, gate, test, evidence</td><td>WP-07 / Gate-C / T-18 / E-09</td></tr></tbody></table><p>The kind is not decoration. A must is not a goal. “A Gateway already exists” is a snapshot, not a promise. “Finish in three days” is an estimate, not an acceptance criterion. “An administrator is always online” is merely an assumption, and possibly a bad one.</p><p>When all of these are flattened into a <code>description</code> field, a later agent can turn aspirations into current facts, estimates into commands, and authority boundaries into ordinary tasks without noticing.</p><h2 id="resolve-conflict-before-drawing-dependencies" tabindex="-1">Resolve conflict before drawing dependencies <a class="header-anchor" href="#resolve-conflict-before-drawing-dependencies" aria-label="Permalink to &quot;Resolve conflict before drawing dependencies&quot;">​</a></h2><p>Long taskbooks are often assembled over time. One section says the phone can publish; a newer appendix says publication authority must remain external. One requirement asks for offline approval while another requires every decision to check the current revision.</p><p>Treat conflicts in three classes:</p><ol><li>Wording differences that can be normalized, such as “work package” and “WP.”</li><li>Conflicts that current repository evidence can settle; record the conclusion and the observation time.</li><li>Contradictions that require human authority; preserve both quotations, the impact, and the options, then stop automatic compilation.</li></ol><p><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-architecture-paper-a1.0" target="_blank" rel="noreferrer">TMPA Architecture Paper A1.0</a> requires a governance reader to preserve conflicts rather than erase them to manufacture a clean state. Planning needs the same discipline. A contradiction that needs a decision must not disappear under more confident prose.</p><h2 id="compile-req-into-wp-do-not-rename-the-table-of-contents" tabindex="-1">Compile REQ into WP; do not rename the table of contents <a class="header-anchor" href="#compile-req-into-wp-do-not-rename-the-table-of-contents" aria-label="Permalink to &quot;Compile REQ into WP; do not rename the table of contents&quot;">​</a></h2><p>A work package is not a section heading. It must answer at least nine questions:</p><ul><li>Which requirements does it satisfy?</li><li>What inspectable artifact does it produce?</li><li>Who writes, who accepts, and who only observes?</li><li>Which WPs does it depend on, and why?</li><li>What are its entry and exit conditions?</li><li>Which tests must run?</li><li>Where is the evidence stored?</li><li>Where does recovery resume after failure?</li><li>Which action requires a human gate?</li></ul><p>For “add mobile approval without changing publication authority,” a small graph might be:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REQ-0042 Authority boundary</span></span>
<span class="line"><span>   ├── WP-02 Freeze the current publication-authority facts</span></span>
<span class="line"><span>   ├── WP-05 Define mobile write actions</span></span>
<span class="line"><span>   │      └── WP-08 Enforce revision + reason + idempotency</span></span>
<span class="line"><span>   └── WP-09 Open-edition boundary regression</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REQ-0048 Windows regression</span></span>
<span class="line"><span>   └── WP-10 Windows binding, reconnect, and revoke tests</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WP-02 ──┐</span></span>
<span class="line"><span>WP-05 ──┼──&gt; Gate-C Security and authority review ──&gt; WP-11 Release candidate</span></span>
<span class="line"><span>WP-09 ──┘</span></span></code></pre></div><p>This diagram combines requirement coverage and execution dependency. Only the latter belongs in the DAG. Two packages referencing the same requirement do not automatically have to be serial.</p><h2 id="derive-the-budget-from-the-graph" tabindex="-1">Derive the budget from the graph <a class="header-anchor" href="#derive-the-budget-from-the-graph" aria-label="Permalink to &quot;Derive the budget from the graph&quot;">​</a></h2><p>A common anti-pattern is to announce “seven days” and squeeze every WP into it. Reverse the order: estimate each package, assign roles and exclusive resources, record non-parallel constraints, then calculate total work, daily capacity, and the critical path.</p><p>Administrator wait time, external API cooldown, queue delays, and human restart time are not agent-effective days. Parallelism is not free either. Two agents modifying the same primary carrier may directly violate the single-writer boundary.</p><p>The useful result is not a pretty Gantt chart. It is an explainable schedule: if Gate-C slips by one day, which packages become blocked? If WP-09 fails, do we rework only the mobile boundary, or return to the authority model?</p><h2 id="deterministic-validation-checks-structure-humans-authorize-exposure" tabindex="-1">Deterministic validation checks structure; humans authorize exposure <a class="header-anchor" href="#deterministic-validation-checks-structure-humans-authorize-exposure" aria-label="Permalink to &quot;Deterministic validation checks structure; humans authorize exposure&quot;">​</a></h2><p>CodeFlowMu&#39;s current <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/skills/pm-long-horizon-planning/references/planning-gate-contract.md" target="_blank" rel="noreferrer">Planning Gate contract</a> separates artifact status, validation status, planning-gate status, and dispatch scope. The validator checks the source digest, coverage, cycles, budgets, resource collisions, placeholders, recovery contracts, and dependencies on superseded revisions. Yet <code>validation_status=passed</code> does not mean “start execution.”</p><p>An administrator decision is bound to the current revision, body digest, and validation digest. Change the body and the prior approval becomes stale. Even a valid approval opens only <code>WP-00</code>, not the entire graph.</p><blockquote><p><strong>Validation asks whether the plan is internally coherent. Approval asks whether we accept the risk of exposing the next boundary of this exact revision.</strong></p></blockquote><p>TMPA Core similarly separates observed state from acceptance authority. Executors, validators, and approvers may read the same persistent artifact, but an executor&#39;s success claim must not upgrade itself into final authorization.</p><h2 id="what-fcop-and-codeflowmu-each-own" tabindex="-1">What FCoP and CodeFlowMu each own <a class="header-anchor" href="#what-fcop-and-codeflowmu-each-own" aria-label="Permalink to &quot;What FCoP and CodeFlowMu each own&quot;">​</a></h2><p>The <a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a> defines collaboration artifacts, path-based state, and event history. It lets TASK, REPORT, ISSUE, and REVIEW records be inspected across tools. It does not compute a critical path, start model sessions, or decide when to dispatch the next WP.</p><p>CodeFlowMu is the engineering rail: PM planning, Runtime dispatch, model sessions, gates, recovery, and PC/PWA surfaces. Collapsing the two turns the protocol into a mythical all-purpose platform and removes testable responsibility from the Runtime.</p><h2 id="a-minimum-preflight-checklist" tabindex="-1">A minimum preflight checklist <a class="header-anchor" href="#a-minimum-preflight-checklist" aria-label="Permalink to &quot;A minimum preflight checklist&quot;">​</a></h2><p>Before an agent team starts a long task, check:</p><ul><li>Was the source read to EOF and bound to a version, SHA, and line count?</li><li>Does every mandatory statement have a stable REQ-ID and source location?</li><li>Are current facts, goals, estimates, assumptions, and authority boundaries separated?</li><li>Does each REQ map to the necessary combination of WP, gate, test, and evidence?</li><li>Are contradictions and unknowns preserved instead of silently decided by the model?</li><li>Is the WP graph acyclic, with budget and critical path derived bottom-up?</li><li>Does each WP have a writer, acceptor, failure result, and recovery entry?</li><li>Is the validation digest bound to the exact body digest?</li><li>Is human approval bound to the current revision and invalidated by changes?</li><li>Is only the first approved execution boundary open?</li></ul><p>This machinery has a cost. A familiar three-line fix does not need a full ledger and DAG; Cursor&#39;s own guidance says quick or familiar work may start directly. The method is for cross-module, long-running, multi-agent work with authority and recovery boundaries.</p><p>It is not a success guarantee either. <a href="https://arxiv.org/abs/2511.04064" target="_blank" rel="noreferrer">E2EDevBench</a> shows that end-to-end software work can fail during planning, execution, and verification. Our compilation pipeline is an engineering response to traceability and governance gaps; it has not been shown to eliminate model misunderstanding, context compression, or handoff loss.</p><p>What it changes is failure diagnosis. Instead of ending with “the agent misunderstood,” we can locate a missed REQ, an unresolved contradiction, an uncovered WP, a wrong dependency, a bypassed gate, or missing evidence. For a team of agents expected to work over time, that diagnostic power is already a substantial engineering result.</p><h2 id="primary-sources" tabindex="-1">Primary sources <a class="header-anchor" href="#primary-sources" aria-label="Permalink to &quot;Primary sources&quot;">​</a></h2><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-architecture-paper-a1.0" target="_blank" rel="noreferrer">TMPA Architecture Paper A1.0</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-core-specification-s1.0" target="_blank" rel="noreferrer">TMPA Core Specification S1.0</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/implementation-case-i1.0" target="_blank" rel="noreferrer">Implementation Case I1.0</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a></li><li><a href="https://cursor.com/blog/plan-mode" target="_blank" rel="noreferrer">Cursor Plan Mode</a></li><li><a href="https://arxiv.org/abs/2511.04064" target="_blank" rel="noreferrer">E2EDevBench</a></li></ul>`,51))])}const v=t(l,[["render",d]]);export{f as __pageData,v as default};
